package org.bukkit.entity;
public interface Player extends HumanEntity, org.bukkit.OfflinePlayer, org.bukkit.inventory.InventoryHolder, org.bukkit.command.CommandSender { int getFoodLevel();int getLevel();float getExp();void setRespawnLocation(org.bukkit.Location location); org.bukkit.GameMode getGameMode(); void setGameMode(org.bukkit.GameMode mode); org.bukkit.inventory.PlayerInventory getInventory(); void kickPlayer(String reason); void sendActionBar(net.kyori.adventure.text.Component message); default boolean isOnline(){return org.bukkit.Bukkit.getPlayer(getUniqueId())!=null;} }
